struct LiqAttr {
    void setLiqReservedBitEnum(LiqReservedBitEnum v) {
        auto rv = v.raw_value();
        bits &= clear_mask<uint8_t, 0, 3>;
        bits |= rv;
    }

    LiqReservedBitEnum getLiqReservedBitEnum() const {
        auto v = bits&get_mask<uint8_t, 0, 3>;
        return LiqReservedBitEnum(uint8_t(v));
    }

    void setLiqIndBitEnum(LiqIndBitEnum v) {
        auto rv = v.raw_value();
        rv <<= 3;
        bits &= clear_mask<uint8_t, 3, 2>;
        bits |= rv;
    }

    LiqIndBitEnum getLiqIndBitEnum() const {
        auto v = bits&get_mask<uint8_t, 3, 2>;
        v >>= 3;
        return LiqIndBitEnum(uint8_t(v));
    }

    void setLiqInternalizedBitEnum(LiqInternalizedBitEnum v) {
        auto rv = v.raw_value();
        rv <<= 5;
        bits &= clear_mask<uint8_t, 5, 1>;
        bits |= rv;
    }

    LiqInternalizedBitEnum getLiqInternalizedBitEnum() const {
        auto v = bits&get_mask<uint8_t, 5, 1>;
        v >>= 5;
        return LiqInternalizedBitEnum(uint8_t(v));
    }

    void setLiqTopOfBookBitEnum(LiqTopOfBookBitEnum v) {
        auto rv = v.raw_value();
        rv <<= 6;
        bits &= clear_mask<uint8_t, 6, 1>;
        bits |= rv;
    }

    LiqTopOfBookBitEnum getLiqTopOfBookBitEnum() const {
        auto v = bits&get_mask<uint8_t, 6, 1>;
        v >>= 6;
        return LiqTopOfBookBitEnum(uint8_t(v));
    }

    void setLiqSelfTradeBitEnum(LiqSelfTradeBitEnum v) {
        auto rv = v.raw_value();
        rv <<= 7;
        bits &= clear_mask<uint8_t, 7, 1>;
        bits |= rv;
    }

    LiqSelfTradeBitEnum getLiqSelfTradeBitEnum() const {
        auto v = bits&get_mask<uint8_t, 7, 1>;
        v >>= 7;
        return LiqSelfTradeBitEnum(uint8_t(v));
    }

    void clear() {
        bits = 0;
    }
    uint8_t bits;
 };

template<typename ostreamT>
ostreamT& operator<<(ostreamT& os, const LiqAttr& v) {
    os << "LiqReservedBitEnum=" << v.getLiqReservedBitEnum();
    os << "|LiqIndBitEnum=" << v.getLiqIndBitEnum();
    os << "|LiqInternalizedBitEnum=" << v.getLiqInternalizedBitEnum();
    os << "|LiqTopOfBookBitEnum=" << v.getLiqTopOfBookBitEnum();
    os << "|LiqSelfTradeBitEnum=" << v.getLiqSelfTradeBitEnum();
    return os;
}

