struct RestatedOrder : Header {
    OutMsgType msgType{OutMsgType::RestatedOrder};
    TimeStamp timestamp;
    UserRefNum userRef;
    RestatedReason reason{RestatedReason::Refresh};
    u16 appendageLength;
    //this member should be only varlen member and the last one
    auto appendage() {return OptionalByLengthRef<OrderRestatedAppendageEntry, AppendixKeyEnum, decltype(appendageLength)&>(begin()+fixed_size(), appendageLength);}
    auto appendage() const {return OptionalByLengthRef<OrderRestatedAppendageEntry, AppendixKeyEnum, const decltype(appendageLength)&>(cbegin()+fixed_size(), appendageLength);}
    char* begin() {return reinterpret_cast<char*>(this);}
    const char* cbegin() const {return reinterpret_cast<const char*>(this);}
    char* end() {return begin()+size();}
    const char* cend() const {return cbegin()+size();}
    static constexpr size_t fixed_size() noexcept {return sizeof(RestatedOrder);}
    size_t size() {return appendage().end()-begin();}
    size_t size() const {return appendage().cend()-cbegin();}
    static size_t wire_size(const char* p) {return reinterpret_cast<const RestatedOrder*>(p)->size();}
};
